import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/theme.dart';
import '../../shared/ui.dart';
import 'patient_registration_screen.dart';

class PatientListScreen extends StatefulWidget { const PatientListScreen({super.key}); @override State<PatientListScreen> createState()=>_PatientListScreenState(); }
class _PatientListScreenState extends State<PatientListScreen>{final search=TextEditingController();List<dynamic> items=[];bool loading=true;String? error;
 @override void initState(){super.initState();load();}
 Future<void> load()async{setState(()=>loading=true);try{final r=await ApiClient.instance.get('/api/v1/patients?limit=100${search.text.trim().isEmpty?'':'&q=${Uri.encodeQueryComponent(search.text.trim())}'}');setState(()=>items=List.from(r['items']??[]));error=null;}catch(e){error=e.toString();}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,16,16,8),child:Row(children:[const Expanded(child:P360Header('Pregnant women',subtitle:'Patients assigned to your facility')),IconButton.filledTonal(onPressed:()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>const PatientRegistrationScreen())).then((_){load();}),icon:const Icon(Icons.add))])),Padding(padding:const EdgeInsets.symmetric(horizontal:16,vertical:8),child:TextField(controller:search,onSubmitted:(_)=>load(),decoration:InputDecoration(hintText:'Search patient name',prefixIcon:const Icon(Icons.search),suffixIcon:IconButton(onPressed:load,icon:const Icon(Icons.arrow_forward))))),Expanded(child:loading?const LoadingView():error!=null?Center(child:Text(error!)):items.isEmpty?const Center(child:Text('No patient records yet.')):RefreshIndicator(onRefresh:load,child:ListView.separated(padding:const EdgeInsets.all(16),itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(context,i){final p=items[i];return Card(child:ListTile(leading:CircleAvatar(backgroundColor:AppColors.paleRose,child:Text((p['full_name']??'P').toString().substring(0,1).toUpperCase(),style:const TextStyle(color:AppColors.crimson,fontWeight:FontWeight.bold))),title:Text(p['full_name']??'Unnamed',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${p['patient_code']??'No patient code'}${p['phone']==null?'':' • ${p['phone']}'}'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>PatientDetailScreen(patientId:p['id'].toString()))));}))) ]);}

class PatientDetailScreen extends StatefulWidget {final String patientId;const PatientDetailScreen({super.key,required this.patientId});@override State<PatientDetailScreen> createState()=>_PatientDetailScreenState();}
class _PatientDetailScreenState extends State<PatientDetailScreen>{Map<String,dynamic>? patient,timeline;String? error;bool loading=true;
 @override void initState(){super.initState();load();}
 Future<void> load()async{try{final p=await ApiClient.instance.get('/api/v1/patients/${widget.patientId}');final t=await ApiClient.instance.get('/api/v1/patients/${widget.patientId}/timeline');setState((){patient=Map<String,dynamic>.from(p);timeline=Map<String,dynamic>.from(t);});}catch(e){error=e.toString();}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext context){if(loading)return const Scaffold(body:LoadingView());if(patient==null)return Scaffold(appBar:AppBar(),body:Center(child:Text(error??'Patient unavailable')));final p=patient!;final q=Map<String,dynamic>.from(p['questionnaire_data']??{});return Scaffold(appBar:AppBar(title:const Text('Patient 360')),body:ListView(padding:const EdgeInsets.all(18),children:[P360Card(child:Row(children:[CircleAvatar(radius:28,backgroundColor:AppColors.blush,child:Text((p['full_name']??'P').toString().substring(0,1),style:const TextStyle(color:AppColors.crimson,fontSize:22))),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p['full_name']??'',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w800)),Text(p['patient_code']??'',style:const TextStyle(color:AppColors.muted))]))])),const SizedBox(height:16),const Text('Pregnancy summary',style:TextStyle(fontWeight:FontWeight.w800,fontSize:18)),P360Card(child:Wrap(spacing:20,runSpacing:16,children:[_Info('Blood group',p['blood_group']),_Info('LMP',p['lmp']),_Info('EDD',p['edd']),_Info('Gravida',p['gravida']),_Info('Parity',p['parity'])])),const SizedBox(height:18),const Text('Assessment information',style:TextStyle(fontWeight:FontWeight.w800,fontSize:18)),...q.entries.map((e)=>P360Card(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e.key.replaceAll('_',' ').toUpperCase(),style:const TextStyle(fontWeight:FontWeight.w800,color:AppColors.crimson)),const SizedBox(height:8),Text(e.value.toString())]))),const SizedBox(height:18),const Text('Clinical timeline',style:TextStyle(fontWeight:FontWeight.w800,fontSize:18)),_TimelineCount('BP measurements',timeline?['bp_measurements']?.length??0),_TimelineCount('Clinical screenings',timeline?['screenings']?.length??0),_TimelineCount('Follow-ups',timeline?['follow_ups']?.length??0),_TimelineCount('Referrals',timeline?['referrals']?.length??0)]));}
}
class _Info extends StatelessWidget{final String label;final dynamic value;const _Info(this.label,this.value);@override Widget build(BuildContext context)=>SizedBox(width:130,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:const TextStyle(color:AppColors.muted,fontSize:12)),Text(value?.toString()??'—',style:const TextStyle(fontWeight:FontWeight.w700))]));}
class _TimelineCount extends StatelessWidget{final String label;final int count;const _TimelineCount(this.label,this.count);@override Widget build(BuildContext context)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(label),trailing:StatusPill('$count records'));}
